examples.template:
MonarchButton(
    text = {{trigger}},
    onClick = {
        step = 0
        open = true
    },
    variant = MonarchButtonVariant.Primary,
)
if (open) {
    MonarchDialog(
        onDismissRequest = { open = false },
        title = when (step) {
            0 -> "Set up two-step verification"
            1 -> "Enter the code from the app"
            else -> "Save your recovery codes"
        },
        description = if (step == 0) {
            "Scan this QR code with an authenticator app, such as 1Password, Google Authenticator or Microsoft Authenticator."
        } else {
            null
        },
        closeButton = true,
        actions = {
            MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Secondary)
            MonarchButton(
                text = if (step == 2) "Done" else "Next",
                onClick = {
                    if (step == 1 && code.length < 6) {
                        codeError = "Enter all 6 digits"
                    } else if (step == 2) {
                        open = false
                    } else {
                        step++
                    }
                },
                variant = MonarchButtonVariant.Primary,
            )
        },
        content = {
            Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
                MonarchText(text = "Step ${step + 1} of 3", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                when (step) {
                    0 -> {
                        qrCode?.let { qr ->
                            Image(
                                painter = qr,
                                contentDescription = "QR code for the authenticator app",
                                modifier = Modifier.size(MonarchTheme.spacing.space24 * 2).align(Alignment.CenterHorizontally),
                            )
                        }
                        MonarchText(
                            text = account,
                            style = MonarchTextStyle.Caption,
                            color = MonarchTheme.colors.textMuted,
                            modifier = Modifier.align(Alignment.CenterHorizontally),
                        )
                        MonarchText(text = "Can’t scan it? Enter this key in the app instead.")
                        MonarchCopyField(value = secret, label = "Setup key")
                    }
                    1 -> MonarchOtpPinInput(
                        value = code,
                        onValueChange = {
                            code = it
                            codeError = null
                        },
                        label = "6-digit code",
                        errorText = codeError,
                    )
                    else -> MonarchRecoveryCodes(
                        codes = listOf({{recoveryCodes.0}}, {{recoveryCodes.1}}, {{recoveryCodes.2}}, {{recoveryCodes.3}}, {{recoveryCodes.4}}, {{recoveryCodes.5}}).map { MonarchRecoveryCode(it) },
                        onAcknowledge = { /* Two-step verification is on. */ },
                    )
                }
            }
        },
    )
}

examples.setupTemplate:
val secret = {{secret}}
val account = {{accountName}}
// A QR code of the otpauth address drawn by the app's own generator; Android has no built-in one.
val qrCode: Painter? = sampleQrPainter()
var open by rememberSaveable { mutableStateOf(true) }
var step by rememberSaveable { mutableIntStateOf(0) }
var code by rememberSaveable { mutableStateOf("") }
var codeError by remember { mutableStateOf<String?>(null) }

